const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Validation check did not atomically claim a valid content_id.');
}
if (!title) {
  throw new Error('Validation check did not receive title.');
}
const storyboard = Array.isArray($json.storyboard_json) ? $json.storyboard_json : [];
const scriptScenes = Array.isArray($json.script_scene_guidance_json) ? $json.script_scene_guidance_json : [];
const subtitles = Array.isArray($json.subtitle_lines_json) ? $json.subtitle_lines_json : [];
const renderSeed = $json.render_manifest_seed_json && typeof $json.render_manifest_seed_json === 'object'
  ? $json.render_manifest_seed_json
  : {};
if (storyboard.length < 2 || storyboard.length > 16) {
  throw new Error('Validation check requires 2 to 16 storyboard scenes (1 title card + up to 15 content scenes).');
}
const forbiddenTextTerms = /subtitle|caption|watermark|logo|lower third|newspaper headline|readable text|text overlay|title text|typography|letters|words on screen|speech bubble|dialogue bubble|thought bubble|comic text/i;
let totalDuration = 0;
let previousSceneNumber = 0;
for (const [index, scene] of storyboard.entries()) {
  const sceneNumber = Number(scene?.scene_number ?? 0);
  const durationSeconds = Number(scene?.duration_seconds ?? 0);
  const narrationText = String(scene?.narration_text ?? '').trim();
  const dialogueLines = Array.isArray(scene?.dialogue_lines) ? scene.dialogue_lines.map((line) => String(line ?? '').trim()).filter(Boolean) : [];
  const visualPrompt = String(scene?.visual_prompt ?? '').trim();
  const assetType = String(scene?.asset_type ?? '').trim();
  const transition = String(scene?.transition ?? '').trim();
  const mood = String(scene?.mood ?? '').trim();
  const musicCue = String(scene?.music_cue ?? '').trim();
  if (sceneNumber !== previousSceneNumber + 1 || sceneNumber !== index + 1) {
    throw new Error('Storyboard scene numbers must be sequential starting at 1.');
  }
  if (!Number.isFinite(durationSeconds) || durationSeconds <= 0) {
    throw new Error('Storyboard scene ' + sceneNumber + ' has invalid duration_seconds.');
  }
  const isContentScene = sceneNumber !== 1;
  if ((isContentScene && (!narrationText || dialogueLines.length === 0)) || !visualPrompt || !transition || !mood || !musicCue) {
    throw new Error('Storyboard scene ' + sceneNumber + ' is missing required scene data (content scenes need narration and dialogue; all scenes need visual_prompt, transition, mood, music_cue).');
  }
  if (!['image', 'video'].includes(assetType)) {
    throw new Error('Storyboard scene ' + sceneNumber + ' has invalid asset_type.');
  }
  if (sceneNumber === 1) {
    if (scene.is_face_image !== true || !String(scene.face_image_title ?? '').trim()) {
      throw new Error('Scene 1 must be the face image and include face_image_title.');
    }
    const titleWords = String(scene.face_image_title ?? '').trim().split(/\s+/).filter(Boolean);
    if (titleWords.length < 2 || titleWords.length > 5) {
      throw new Error('Scene 1 face_image_title must be 2 to 5 words.');
    }
    if (durationSeconds > 4.25) {
      throw new Error('Scene 1 title card must be 4 seconds or shorter.');
    }
  } else if (String(scene.face_image_title ?? '').trim()) {
    throw new Error('Only scene 1 may include face_image_title.');
  }
  if (forbiddenTextTerms.test(visualPrompt)) {
    throw new Error('Storyboard scene ' + sceneNumber + ' visual_prompt appears to request visible text or overlays. The title belongs in face_image_title metadata only.');
  }
  totalDuration += durationSeconds;
  previousSceneNumber = sceneNumber;
}
if (subtitles.length === 0) {
  throw new Error('subtitle_lines_json metadata is required for review, even though render subtitles stay disabled.');
}
if (!renderSeed.output || !Array.isArray(renderSeed.timeline)) {
  throw new Error('render_manifest_seed_json must include output and timeline.');
}
if (!renderSeed.subtitles || renderSeed.subtitles.enabled !== false) {
  throw new Error('render_manifest_seed_json.subtitles.enabled must be false.');
}
if (renderSeed.timeline.length && renderSeed.timeline.length !== storyboard.length) {
  throw new Error('render_manifest_seed_json.timeline must match storyboard scene count.');
}
const targetDurationSeconds = Number($json.target_duration_seconds ?? 0);
if (Number.isFinite(targetDurationSeconds) && targetDurationSeconds > 0) {
  const drift = Math.abs(totalDuration - targetDurationSeconds);
  if (drift > Math.max(3, targetDurationSeconds * 0.65)) {
    throw new Error('Storyboard total duration is too far from target_duration_seconds.');
  }
}
return [{
  json: {
    content_id: contentId,
    title,
    scene_count: storyboard.length,
    total_duration_seconds: Number(totalDuration.toFixed(2)),
    validation_summary: {
      scene_count: storyboard.length,
      script_scene_count: scriptScenes.length,
      subtitle_line_count: subtitles.length,
      total_duration_seconds: Number(totalDuration.toFixed(2)),
      title_card_duration_seconds: Number(storyboard[0]?.duration_seconds ?? 0),
      subtitles_enabled: false,
      checked_at: new Date().toISOString()
    },
    run_started_at: new Date().toISOString()
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Prepare Validation SQL Values received invalid content_id.');
}
const startedAt = new Date(String($json.run_started_at ?? new Date().toISOString()));
const durationMs = Math.max(0, Date.now() - startedAt.getTime());
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    validation_summary_json_sql: JSON.stringify($json.validation_summary ?? {}).replaceAll("'", "''"),
    scene_count_sql: Number($json.scene_count ?? 0),
    total_duration_seconds_sql: Number($json.total_duration_seconds ?? 0),
    duration_ms_sql: Number.isFinite(durationMs) ? durationMs : 0,
  }
}];
